const { useState } = React;

function App() {
  const [page, setPage] = useState("signin");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(false);
  const [errors, setErrors] = useState({});

  function validate() {
    const newErrors = {};
    if (!username.trim()) newErrors.username = "Username is required.";
    if (!password.trim()) newErrors.password = "Password is required.";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleSignIn(e) {
    e.preventDefault();
    if (validate()) {
      alert(`Signed in as ${username} (Remember me: ${remember})`);
      // Reset form or do something else
    }
  }

  if (page === "register") {
    return (
      <main style={styles.main}>
        <section style={styles.card} aria-label="Register page">
          <h2 style={styles.heading}>Create an account</h2>
          <p style={{ marginBottom: 20 }}>
            This is a placeholder for the Register page.
          </p>
          <button
            type="button"
            onClick={() => setPage("signin")}
            style={styles.linkButton}
          >
            Back to Sign in
          </button>
        </section>
      </main>
    );
  }

  return (
    <main style={styles.main}>
      <section style={styles.card} aria-label="Sign in form">
        <div style={styles.iconWrapper} aria-hidden="true">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={1.5}
            stroke="currentColor"
            style={styles.userIcon}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.5 20.25v-1.125a6.375 6.375 0 0112.75 0v1.125"
            />
          </svg>
        </div>
        <h1 style={styles.heading}>Welcome back</h1>
        <form onSubmit={handleSignIn} noValidate>
          <label htmlFor="username" style={styles.label}>
            Username
          </label>
          <input
            id="username"
            name="username"
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={styles.input}
            aria-describedby={errors.username ? "username-error" : undefined}
            aria-invalid={errors.username ? "true" : "false"}
          />
          {errors.username && (
            <p id="username-error" role="alert" style={styles.error}>
              {errors.username}
            </p>
          )}

          <label htmlFor="password" style={styles.label}>
            Password
          </label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={styles.input}
            aria-describedby={errors.password ? "password-error" : undefined}
            aria-invalid={errors.password ? "true" : "false"}
          />
          {errors.password && (
            <p id="password-error" role="alert" style={styles.error}>
              {errors.password}
            </p>
          )}

          <div style={styles.rememberForgot}>
            <label style={styles.checkboxLabel}>
              <input
                type="checkbox"
                checked={remember}
                onChange={(e) => setRemember(e.target.checked)}
                style={styles.checkbox}
              />
              Remember me
            </label>
            <a href="#" style={styles.forgotLink} onClick={(e) => e.preventDefault()}>
              Forgot password?
            </a>
          </div>

          <button type="submit" style={styles.signInButton}>
            Sign in
          </button>

          <div style={styles.dividerWrapper} aria-hidden="true">
            <hr style={styles.divider} />
          </div>

          <button
            type="button"
            style={styles.googleButton}
            onClick={() => alert("Continue with Google clicked")}
          >
            Continue with Google
          </button>

          <p style={styles.createAccount}>
            <button
              type="button"
              onClick={() => setPage("register")}
              style={styles.linkButton}
            >
              Create an account
            </button>
          </p>
        </form>
      </section>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #f9f7f6;
          color: #222;
        }
        button:focus,
        input:focus,
        a:focus {
          outline: 2px solid #4a90e2;
          outline-offset: 2px;
        }
      `}</style>
    </main>
  );
}

